package studio.teja.airbridge;
import android.graphics.*;import android.view.*;import android.widget.Toast;
/** One-time, visible calibration over Instagram. Touches position a marker, not the app. */
public final class OverlayPicker extends View {
 public static volatile boolean showing;
 private final SwipeService service;private final WindowManager windows;private final Paint paint=new Paint(3);private float x,y;private final RectF save=new RectF(),cancel=new RectF();private boolean removed;
 public static void show(SwipeService s){new android.os.Handler(android.os.Looper.getMainLooper()).post(()->{try{OverlayPicker p=new OverlayPicker(s);WindowManager.LayoutParams a=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);a.gravity=Gravity.TOP|Gravity.LEFT;showing=true;p.windows.addView(p,a);}catch(Exception e){Toast.makeText(s,"Could not show calibration",Toast.LENGTH_SHORT).show();}});}
 private OverlayPicker(SwipeService s){super(s);service=s;windows=s.getSystemService(WindowManager.class);setContentDescription("Comments button calibration. Tap the comments icon to position the marker, then Save. No underlying button is pressed.");}
 private void text(Canvas c,String s,float cx,float cy,float size){paint.setColor(Color.WHITE);paint.setTextSize(size);paint.setTextAlign(Paint.Align.CENTER);paint.setTypeface(Typeface.create("sans-serif-medium",0));c.drawText(s,cx,cy,paint);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();if(x==0){int[] origin=new int[2];getLocationOnScreen(origin);android.graphics.Rect bounds=windows.getMaximumWindowMetrics().getBounds();android.content.SharedPreferences prefs=service.getSharedPreferences("bridge",0);x=bounds.left+bounds.width()*prefs.getFloat("commentX",.91f)-origin[0];y=bounds.top+bounds.height()*prefs.getFloat("commentY",.55f)-origin[1];}c.drawColor(0x55000000);save.set(w*.08f,h*.065f,w*.46f,h*.12f);cancel.set(w*.54f,h*.065f,w*.92f,h*.12f);paint.setColor(0xff173940);c.drawRoundRect(save,28,28,paint);c.drawRoundRect(cancel,28,28,paint);text(c,"SAVE",save.centerX(),save.centerY()+14,w*.038f);text(c,"CANCEL",cancel.centerX(),cancel.centerY()+14,w*.038f);text(c,"Tap the Instagram comments icon",w*.5f,h*.16f,w*.037f);text(c,"Then Save. This only positions the marker.",w*.5f,h*.19f,w*.030f);paint.setColor(0xff83e1ce);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(5);c.drawCircle(x,y,w*.037f,paint);c.drawLine(x-w*.06f,y,x+w*.06f,y,paint);c.drawLine(x,y-w*.06f,x,y+w*.06f,paint);paint.setStyle(Paint.Style.FILL);}
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP){if(save.contains(e.getX(),e.getY())){int[] origin=new int[2];getLocationOnScreen(origin);android.graphics.Rect bounds=windows.getMaximumWindowMetrics().getBounds();service.getSharedPreferences("bridge",0).edit().putFloat("commentX",(origin[0]+x-bounds.left)/bounds.width()).putFloat("commentY",(origin[1]+y-bounds.top)/bounds.height()).putBoolean("commentsCalibrated",true).apply();remove();Toast.makeText(service,"Instagram comments button saved",Toast.LENGTH_SHORT).show();return true;}if(cancel.contains(e.getX(),e.getY())){remove();return true;}}if(e.getAction()==MotionEvent.ACTION_DOWN||e.getAction()==MotionEvent.ACTION_MOVE){if(!save.contains(e.getX(),e.getY())&&!cancel.contains(e.getX(),e.getY())){x=e.getX();y=e.getY();invalidate();}}return true;}
 private void remove(){if(!removed){removed=true;showing=false;windows.removeView(this);}}
}
